<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Audit Log</title><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/attendance.css"></head><body><a class="skip-link" href="#main">Lewati ke konten utama</a><main id="main" class="attendance-page" tabindex="-1"><header><a href="/dashboard">← Dashboard</a><div><span>Keamanan</span><h1>Audit log</h1><p>Catatan read-only aktivitas penting aplikasi.</p></div></header><form id="audit-filter" class="toolbar" role="search"><label class="sr-only" for="audit-action">Cari aksi</label><input id="audit-action" name="action" placeholder="Cari aksi"><label class="sr-only" for="audit-actor">Cari pengguna</label><input id="audit-actor" name="actor" placeholder="Cari pengguna"><button>Cari</button></form><p id="audit-status" role="status" aria-live="polite"></p><div class="report-table" tabindex="0" aria-label="Tabel audit log dapat digulir"><table><thead><tr><th>Waktu</th><th>Pengguna</th><th>Role</th><th>Aksi</th><th>Entitas</th><th>Detail</th></tr></thead><tbody id="audit-rows"></tbody></table></div><nav id="audit-pagination" aria-label="Pagination audit log"></nav></main><dialog id="audit-dialog" aria-labelledby="audit-dialog-title"><form method="dialog"><button aria-label="Tutup detail audit">×</button></form><h2 id="audit-dialog-title">Detail audit</h2><pre id="audit-detail"></pre></dialog><script type="module" src="/assets/js/audit.js"></script></body></html>
